insert into venues ("id", "name", "address", "neighborhood", "lat", "lng", "capacity", "parkingInfo", "transitInfo") values
  ('dodger-stadium', 'Dodger Stadium', '1000 Vin Scully Ave, Los Angeles, CA 90012', 'downtown', 34.0739, -118.24, 56000, 'On-site parking available for $30-$50; lots open 2 hours before first pitch.', 'Dodger Stadium Express shuttle from Union Station (free with game ticket); Metro B/D Line to Union Station.'),
  ('sofi-stadium', 'SoFi Stadium', '1001 Stadium Dr, Inglewood, CA 90301', 'south-la', 33.9535, -118.3392, 70240, 'Prepaid parking $60-$100 at Hollywood Park; rideshare drop-off on Prairie Ave.', 'Metro C Line to Downtown Inglewood station, then shuttle to stadium on game days.'),
  ('crypto-arena', 'Crypto.com Arena', '1111 S Figueroa St, Los Angeles, CA 90015', 'downtown', 34.043, -118.2673, 19068, 'Multiple lots surrounding LA Live; expect $20-$40. Book via ParkWhiz for discounts.', 'Metro A/E Line to Pico station (one block away); Metro B/D to 7th/Metro then walk 10 min.'),
  ('bmo-stadium', 'BMO Stadium', '3939 S Figueroa St, Los Angeles, CA 90037', 'south-la', 34.0128, -118.2842, 22000, 'Limited on-site parking $40; street parking and private lots available on Figueroa.', 'Metro E Line to Expo/Vermont station then walk 15 min; DASH bus F from downtown.'),
  ('dignity-health-sports-park', 'Dignity Health Sports Park', '18400 S Avalon Blvd, Carson, CA 90746', 'south-bay', 33.8644, -118.2611, 27000, 'Free general parking in surrounding lots; VIP/premium parking $25.', 'Metro C Line to Avalon station, then bus 246 southbound to Victoria St; limited transit access.'),
  ('intuit-dome', 'Intuit Dome', '3930 W Century Blvd, Inglewood, CA 90303', 'south-la', 33.9458, -118.3418, 18000, 'Prepaid parking required ($30-$60); adjacent structures and rideshare plaza available.', 'Metro C Line to Downtown Inglewood station, then shuttle or 15-min walk via Century Blvd.'),
  ('la-memorial-coliseum', 'Los Angeles Memorial Coliseum', '3911 S Figueroa St, Los Angeles, CA 90037', 'south-la', 34.0141, -118.2879, 77500, 'Lots around Exposition Park $20-$40; arrive early as lots fill quickly on game days.', 'Metro E Line to Expo Park/USC station (adjacent); multiple Metro bus lines serve Figueroa.'),
  ('rose-bowl', 'Rose Bowl Stadium', '1001 Rose Bowl Dr, Pasadena, CA 91103', 'san-gabriel-valley', 34.1613, -118.1676, 88565, 'On-site parking $25-$50; free remote lots with shuttle service on major event days.', 'Metro A Line to Memorial Park station, then Pasadena Transit or shuttle to Rose Bowl.'),
  ('pauley-pavilion', 'Pauley Pavilion', '555 Westwood Plaza, Los Angeles, CA 90095', 'westside', 34.0702, -118.4468, 13800, 'UCLA campus parking structures $15-$20; Lot 4 closest to venue.', 'Metro B/D Line to Westwood/UCLA station; Big Blue Bus lines 1, 2, 8 to Westwood Blvd.'),
  ('galen-center', 'Galen Center', '3400 S Figueroa St, Los Angeles, CA 90089', 'south-la', 34.0223, -118.286, 10258, 'USC parking structures on Jefferson Blvd ($15-$20); street metered parking on Figueroa.', 'Metro E Line to Expo Park/USC station, walk 5 min north; DASH F bus from downtown.'),
  ('firestone-fieldhouse', 'Firestone Fieldhouse', '24255 Pacific Coast Hwy, Malibu, CA 90263', 'westside', 34.0358, -118.7098, 3104, 'Free parking in campus lots; overflow parking along PCH on busy nights.', 'Limited transit; Metro 534 bus along PCH from Santa Monica. Driving recommended.'),
  ('gersten-pavilion', 'Gersten Pavilion', '1 LMU Dr, Los Angeles, CA 90045', 'westside', 33.9709, -118.4175, 4156, 'Free campus parking on game days in Lots H and F; enter from Lincoln Blvd.', 'Metro Bus 115 along Lincoln Blvd, or Culver City Bus 1 to LMU campus.'),
  ('matadome', 'The Matadome (Premier America Credit Union Arena)', '18111 Nordhoff St, Northridge, CA 91330', 'san-fernando-valley', 34.2367, -118.5286, 2600, 'CSUN parking structures B5 and G3 ($10); free street parking on Zelzah Ave after 6 PM.', 'Metro G Line (Orange) to Nordhoff station, then CSUN shuttle or 15-min walk east.'),
  ('walter-pyramid', 'Walter Pyramid', '6300 State University Dr, Long Beach, CA 90815', 'gateway-cities', 33.7872, -118.1131, 5000, 'Campus parking lots $10 on event days; Lot G12 closest to Pyramid.', 'Metro A Line to Downtown Long Beach, then Long Beach Transit 91/93 to campus.'),
  ('elac-stadium', 'ELAC Weingart Stadium', '1301 Avenida Cesar Chavez, Monterey Park, CA 91754', 'east-la', 34.0233, -118.1614, 6000, 'Free parking in campus lots; additional overflow parking on Collegian Ave.', 'Metro B/D Line to Union Station, then Metro 70 bus eastbound to Atlantic/Cesar Chavez.'),
  ('lacc-athletic-field', 'LACC Athletic Field & Gym', '855 N Vermont Ave, Los Angeles, CA 90029', 'downtown', 34.0879, -118.2917, 2000, 'Free campus parking in Lot C off Monroe St; metered street parking on Vermont.', 'Metro B Line to Vermont/Santa Monica station (2 blocks); Metro buses 204, 754 on Vermont.'),
  ('lavc-athletic-complex', 'LAVC Monarch Gym & Athletic Fields', '5800 Fulton Ave, Valley Glen, CA 91401', 'san-fernando-valley', 34.1867, -118.4211, 1500, 'Free campus parking in Lot 1 off Fulton Ave; street parking available on Burbank Blvd.', 'Metro G Line (Orange) to Laurel Canyon station, then walk or bus south on Laurel Canyon Blvd.'),
  ('el-camino-stadium', 'El Camino College Murdock Stadium', '16007 Crenshaw Blvd, Torrance, CA 90506', 'south-bay', 33.8668, -118.3363, 8000, 'Free parking in campus lots off Crenshaw Blvd and Manhattan Beach Blvd.', 'Metro Bus 210 along Crenshaw Blvd; South Bay Shuttle from Metro C Line Crenshaw station.'),
  ('smc-corsair-field', 'SMC Corsair Field & Pavilion', '1744 Pearl St, Santa Monica, CA 90405', 'westside', 34.0137, -118.4696, 2000, 'Free campus parking in lots on Pico Blvd; metered street parking on Pearl St.', 'Metro E Line to 17th St/SMC station (adjacent); Big Blue Bus lines 7 and Rapid 7.'),
  ('mt-sac-hilmer-lodge', 'Mt. SAC Hilmer Lodge Stadium', '1100 N Grand Ave, Walnut, CA 91789', 'san-gabriel-valley', 34.0489, -117.8456, 12000, 'Free parking in campus lots off Grand Ave and Temple Ave.', 'Foothill Transit Line 286 to Mt. SAC campus; limited transit, driving recommended.'),
  ('cerritos-college-stadium', 'Cerritos College Falcon Stadium', '11110 Alondra Blvd, Norwalk, CA 90650', 'gateway-cities', 33.8868, -118.0879, 4000, 'Free parking in campus lots off Studebaker Rd and Alondra Blvd.', 'Metro Bus 460 on Norwalk Blvd; Norwalk Transit line 7 along Alondra Blvd.'),
  ('pcc-robinson-stadium', 'PCC Robinson Stadium & Hutto-Patterson Gymnasium', '1570 E Colorado Blvd, Pasadena, CA 91106', 'san-gabriel-valley', 34.1422, -118.1198, 3500, 'Free campus parking off Hill Ave; street parking on Colorado Blvd.', 'Metro A Line to Lake station, then Pasadena Transit 10 to campus.'),
  ('cal-poly-pomona-kellogg-gym', 'Cal Poly Pomona Kellogg Gym', '3801 W Temple Ave, Pomona, CA 91768', 'san-gabriel-valley', 34.0565, -117.8226, 5000, 'Campus parking $5-$10; Lot F closest to athletics complex.', 'Foothill Transit 194/291 to campus; Metrolink to Pomona station, then Foothill Transit.'),
  ('csuf-athletics', 'CSUF Titan Athletics Complex', '800 N State College Blvd, Fullerton, CA 92831', 'san-gabriel-valley', 33.8817, -117.8854, 4000, 'Campus parking structures $5-$10; Lot A near Anderson Field; Lot G near Titan Gym.', 'OCTA Bus 43 or 47 to State College Blvd; Metrolink to Fullerton station, then OCTA 43.'),
  ('pomona-pitzer-athletics', 'Pomona-Pitzer Athletics Complex', '610 N College Ave, Claremont, CA 91711', 'san-gabriel-valley', 34.0967, -117.711, 2500, 'Free parking in Claremont Colleges lots on weekends; metered street parking on College Ave.', 'Metrolink San Bernardino Line to Claremont station, then walk or campus shuttle north.'),
  ('calstate-la-athletics', 'Cal State LA Golden Eagle Arena', '5151 State University Dr, Los Angeles, CA 90032', 'east-la', 34.0673, -118.1685, 2500, 'Campus Lot 2 and Lot 5 ($5-$8); street parking on State University Dr after 6 PM.', 'Metro B Line to Cal State LA station (on campus); Metro Bus 70 on Valley Blvd.'),
  ('occidental-athletics', 'Occidental College Athletic Fields', '1600 Campus Rd, Los Angeles, CA 90041', 'east-la', 34.1239, -118.2073, 2000, 'Free campus parking on weekends in Lot 1 and Lot 5; street parking on Campus Rd.', 'Metro Bus 81 along York Blvd; Metro B/D Line to Highland Park station, then bus north.'),
  ('rio-hondo-athletics', 'Rio Hondo College Athletic Complex', '3600 Workman Mill Rd, Whittier, CA 90601', 'san-gabriel-valley', 33.9744, -117.9817, 3000, 'Free campus parking in Lots 1-4 off Workman Mill Rd.', 'Metro Bus 484 along Workman Mill Rd; limited transit access, driving recommended.'),
  ('citrus-athletics', 'Citrus College Athletic Complex', '1000 W Foothill Blvd, Glendora, CA 91741', 'san-gabriel-valley', 34.1044, -117.8652, 3500, 'Free parking in campus lots off Foothill Blvd; Lot 1 is closest to the stadium.', 'Foothill Transit Line 187 along Foothill Blvd; driving recommended for evening events.'),
  ('west-la-athletics', 'West LA College Athletic Complex', '9000 Overland Ave, Culver City, CA 90230', 'westside', 34.0268, -118.4012, 1500, 'Free campus parking in main lot off Overland Ave.', 'Metro Bus 12 or Culver City Bus 6 along Overland Ave; Metro E Line to Culver City station, then bus north.'),
  ('compton-athletics', 'Compton College Athletic Complex', '1111 E Artesia Blvd, Compton, CA 90221', 'south-la', 33.8894, -118.2194, 2000, 'Free campus parking in lots off Artesia Blvd.', 'Metro Bus 51 along Artesia Blvd; Metro A Line to Compton station, then bus east.'),
  ('harbor-athletics', 'Harbor College Athletic Complex', '1111 Figueroa Place, Wilmington, CA 90744', 'south-bay', 33.7879, -118.2867, 2000, 'Free campus parking in main lot off Figueroa Place.', 'Metro Bus 205 along Pacific Coast Hwy; limited transit, driving recommended.'),
  ('lapc-athletics', 'LA Pierce College Athletic Complex', '6201 Winnetka Ave, Woodland Hills, CA 91371', 'san-fernando-valley', 34.1924, -118.5752, 5000, 'Free campus parking in Lots 9 and 11 off Winnetka Ave.', 'Metro Bus 164 or 161 along Winnetka Ave; limited transit access.'),
  ('csudh-athletics', 'CSUDH Toro Athletics Complex', '1000 E Victoria St, Carson, CA 90747', 'south-bay', 33.8633, -118.2564, 3000, 'Campus parking lots $5-$10; Lot 7 closest to athletics complex.', 'Metro Bus 205 along Victoria St; Metro C Line to Carson station, then walk or bus.'),
  ('la-southwest-athletics', 'LA Southwest College Athletic Complex', '1600 W Imperial Hwy, Los Angeles, CA 90047', 'south-la', 33.9292, -118.3148, 1500, 'Free campus parking in main lot off Imperial Hwy.', 'Metro Bus 115 along Imperial Hwy; Metro A Line to Vermont/Athens, then bus west.'),
  ('glendale-cc-athletics', 'Glendale Community College Athletic Complex', '1500 N Verdugo Rd, Glendale, CA 91208', 'san-fernando-valley', 34.1731, -118.2548, 3000, 'Campus parking Lot 1 and Lot 3 ($3-$5); free street parking on Verdugo Rd evenings.', 'Metro Bus 90 or Glendale Beeline Bus 1 along Verdugo Rd.')
