insert into featured ("id", "type", "title", "description", "eventId", "imageUrl", "publishDate") values
  ('gotw-la-dodgers-20260919', 'game-of-week', 'The Best Rivalry in Baseball: Dodgers vs. San Francisco Giants', 'Dating back to New York, this one defines the NL West. The San Francisco Giants come to Dodger Stadium for a Saturday showdown. This is appointment viewing.', 'la-dodgers-20260919', NULL, '2026-09-12T00:00:00Z'),
  ('gotw-la-chargers-20260913', 'game-of-week', 'Chargers vs. Arizona Cardinals', 'The Chargers host the Arizona Cardinals at SoFi Stadium this Sunday. A marquee matchup you won''t want to miss.', 'la-chargers-20260913', NULL, '2026-09-12T00:00:00Z'),
  ('gotw-la-rams-20260922', 'game-of-week', 'Rams vs. New York Giants', 'The New York Giants come to town for a Tuesday clash at SoFi Stadium. The Rams are looking to put on a show for the home crowd.', 'la-rams-20260922', NULL, '2026-09-12T00:00:00Z'),
  ('gem-long-beach-state-49ers-20260912-womens-college-volleyball', 'hidden-gem', 'Women''s Volleyball: LBSU vs. San José State Spartans', 'Women''s volleyball is having a moment, and LBSU is part of it. Catch them hosting San José State Spartans at Walter Pyramid.', 'long-beach-state-49ers-20260912-womens-college-volleyball', NULL, '2026-09-12T00:00:00Z')
